args.command:
try_rustowlc() {
  printf '#!/bin/sh\nprintf %%s %s\nexit 0\n' "$1" > /tmp/fakebin/rustowlc; chmod +x /tmp/fakebin/rustowlc
  rm -rf /tmp/nw && mkdir -p /tmp/nw && echo 'fn main(){}' > /tmp/nw/m.rs
  cd /workspace && PATH=/tmp/fakebin:/usr/bin:/bin ./executable check /tmp/nw/m.rs 2>&1 | grep -vE 'toolchain|backend' 
}
try_rustowlc "'{\"message\":\"hi\",\"level\":\"warning\",\"spans\":[]}\n'"
echo ===
try_rustowlc "'{\"reason\":\"compiler-message\",\"message\":{\"message\":\"hi\",\"level\":\"warning\",\"spans\":[]}}\n'"

printf '#!/bin/sh
exit 1
' > /tmp/fakebin/cargo; chmod +x /tmp/fakebin/cargo
try_rustowlc() {
  printf '#!/bin/sh
printf %%s %s
exit 0
' "$1" > /tmp/fakebin/rustowlc; chmod +x /tmp/fakebin/rustowlc
  cd /workspace && PATH=/tmp/fakebin:/usr/bin:/bin ./executable check /tmp/nw/m.rs 2>&1 | grep -vE 'toolchain|backend'
}
try_rustowlc "'{"message":"hi","level":"warning","spans":[]}
'"
echo ===; try_rustowlc "'{"rustowl":{}}
'"
echo ===; try_rustowlc "'{"type":"analyze"}
'"

